1	// RBC Financial Credit Card CSV Parser
2	// Expected format: "Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
3	// Date format: M/D/YYYY (e.g., "6/10/2024")
4	// Amount: In CAD$ column, can be positive or negative
5	
6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
8	
9	export class RBCFinancialParser extends BaseCSVParser {
10		parse(csvContent: string): CSVParseResult {
11			const transactions: ParsedTransaction[] = [];
12			const errors: string[] = [];
13	
14			try {
15				csvContent = this.removeBOM(csvContent);
16				const rows = this.parseCSV(csvContent);
17	
18				if (rows.length < 2) {
19					errors.push('CSV file is empty or has no data rows');
20					return { transactions, errors };
21				}
22	
23				// Validate header
24				const header = rows[0];
25				if (!this.validateFormat(csvContent)) {
26					errors.push(
27						'Invalid RBC Financial CSV format. Expected columns: Account Type, Account Number, Transaction Date, Description 1, CAD$'
28					);
29					return { transactions, errors };
30				}
31	
32				// Find column indices
33				const dateIdx = header.findIndex(
34					(h) =>
35						h.toLowerCase().includes('transaction date') || h.toLowerCase() === 'transaction date'
36				);
37				const desc1Idx = header.findIndex((h) => h.toLowerCase().includes('description 1'));
38				const desc2Idx = header.findIndex((h) => h.toLowerCase().includes('description 2'));
39				const amountIdx = header.findIndex(
40					(h) => h.toLowerCase().includes('cad$') || h.toLowerCase().includes('cad')
41				);
42	
43				if (dateIdx === -1 || desc1Idx === -1 || amountIdx === -1) {
44					errors.push('Could not find required columns in CSV header');
45					return { transactions, errors };
46				}
47	
48				// Parse data rows
49				for (let i = 1; i < rows.length; i++) {
50					const row = rows[i];
51					if (row.length < 6) continue; // Skip incomplete rows
52	
53					const dateStr = row[dateIdx]?.trim();
54					const description1 = row[desc1Idx]?.trim();
55					const description2 = row[desc2Idx]?.trim();
56					const amountStr = row[amountIdx]?.trim();
57	
58					// Skip empty rows
59					if (!dateStr && !description1 && !amountStr) continue;
60	
61					// Parse date
62					const transaction_date = this.parseDate(dateStr);
63					if (!transaction_date) {
64						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
65						continue;
66					}
67	
68					// Parse amount
69					const rawAmount = this.parseAmount(amountStr);
70					if (rawAmount === null) {
71						errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
72						continue;
73					}
74	
75					// RBC uses negative for expenses — keep as-is (#{#trn2d})
76					const amount = this.normalizeAmount(rawAmount, false);
77	
78					// Combine descriptions (some transactions have both Description 1 and Description 2)
79					let vendor_name = description1 || '';
80					if (description2) {
81						vendor_name = vendor_name ? `${vendor_name} ${description2}` : description2;
82					}
83	
84					// Validate vendor name
85					if (!vendor_name) {
86						errors.push(`Row ${i + 1}: Missing vendor name/description`);
87						continue;
88					}
89	
90					transactions.push({
91						transaction_date,
92						vendor_name,
93						amount
94					});
95				}
96			} catch (e: any) {
97				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
98			}
99	
100			return { transactions, errors };
101		}
102	
103		validateFormat(csvContent: string): boolean {
104			try {
105				csvContent = this.removeBOM(csvContent);
106				const rows = this.parseCSV(csvContent);
107				if (rows.length === 0) return false;
108	
109				const header = rows[0];
110				// Check for RBC-specific columns
111				// RBC CSV should have at least 7 columns
112				if (header.length < 7) return false;
113	
114				const expectedColumns = ['account type', 'transaction date', 'description 1'];
115				// Also need to check for CAD$ column (or CAD)
116				const hasCAD = header.some((h) => h.toLowerCase().includes('cad'));
117				if (!hasCAD) return false;
118				return this.hasExpectedColumns(header, expectedColumns);
119			} catch {
120				return false;
121			}
122		}
123	}
