1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	import { RBCFinancialParser } from '../RBCFinancialParser';
5	
6	describe('RBCFinancialParser', () => {
7		const parser = new RBCFinancialParser();
8	
9		// Helper to load CSV files from resources
10		const loadCSV = (filename: string): string => {
11			const filePath = join(process.cwd(), 'resources', filename);
12			return readFileSync(filePath, 'utf-8');
13		};
14	
15		describe('validateFormat', () => {
16			it('should validate correct RBC Financial CSV format', () => {
17				const csv = loadCSV('RBCFinancialSample.csv');
18				expect(parser.validateFormat(csv)).toBe(true);
19			});
20	
21			it('should reject invalid CSV format', () => {
22				const invalidCSV = `Date,Merchant,Amount
23	01/01/2024,Store,100.00`;
24				expect(parser.validateFormat(invalidCSV)).toBe(false);
25			});
26	
27			it('should reject empty CSV', () => {
28				expect(parser.validateFormat('')).toBe(false);
29			});
30	
31			it('should reject CSV with too few columns', () => {
32				const invalidCSV = `"Account Type","Account Number","Transaction Date"
33	Visa,4514015001949444,6/10/2024`;
34				expect(parser.validateFormat(invalidCSV)).toBe(false);
35			});
36	
37			it('should handle CSV with BOM', () => {
38				const csv = loadCSV('RBCFinancialSample.csv');
39				expect(parser.validateFormat(csv)).toBe(true);
40			});
41		});
42	
43		describe('parse', () => {
44			it('should parse sample data correctly (#{#trn2d})', () => {
45				const csv = loadCSV('RBCFinancialSample.csv');
46				const result = parser.parse(csv);
47	
48				expect(result.errors).toEqual([]);
49				expect(result.transactions).toHaveLength(2);
50	
51				// Check first transaction (expense, stays negative)
52				expect(result.transactions[0]).toEqual({
53					transaction_date: '2024-06-10',
54					vendor_name: 'PEACE HILLS INSURANCE 780-424-3986 AB',
55					amount: -2445.0 // -2445.00 (expense), negative = expense
56				});
57	
58				// Check second transaction (credit, stays positive)
59				expect(result.transactions[1]).toEqual({
60					transaction_date: '2024-06-25',
61					vendor_name: 'CIBC TORONTO',
62					amount: 315.9 // 315.90 (credit), positive = refund
63				});
64			});
65	
66			it('should keep expenses as negative amounts (#{#trn2d})', () => {
67				const csv = loadCSV('RBCFinancialSample.csv');
68				const result = parser.parse(csv);
69				expect(result.transactions[0].amount).toBe(-2445.0); // Expense stays negative
70			});
71	
72			it('should keep credits as positive amounts (#{#trn2d})', () => {
73				const csv = loadCSV('RBCFinancialSample.csv');
74				const result = parser.parse(csv);
75				expect(result.transactions[1].amount).toBe(315.9); // Credit stays positive
76			});
77	
78			it('should parse dates in M/D/YYYY format', () => {
79				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
80	Visa,4514015001949444,12/31/2023,,"Test Store",,-100.00,,`;
81				const result = parser.parse(csv);
82	
83				expect(result.transactions[0].transaction_date).toBe('2023-12-31');
84			});
85	
86			it('should handle dates with single digit month/day', () => {
87				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
88	Visa,4514015001949444,1/5/2024,,"Test Store",,-50.00,,`;
89				const result = parser.parse(csv);
90	
91				expect(result.transactions[0].transaction_date).toBe('2024-01-05');
92			});
93	
94			it('should combine Description 1 and Description 2', () => {
95				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
96	Visa,4514015001949444,6/10/2024,,"Store Name","Location Info",-100.00,,`;
97				const result = parser.parse(csv);
98	
99				expect(result.transactions[0].vendor_name).toBe('Store Name Location Info');
100			});
101	
102			it('should handle Description 1 only', () => {
103				const csv = loadCSV('RBCFinancialSample.csv');
104				const result = parser.parse(csv);
105				expect(result.transactions[1].vendor_name).toBe('CIBC TORONTO');
106			});
107	
108			it('should report errors for invalid dates', () => {
109				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
110	Visa,4514015001949444,invalid-date,,"Test Store",,-100.00,,`;
111				const result = parser.parse(csv);
112	
113				expect(result.errors.length).toBeGreaterThan(0);
114				expect(result.errors[0]).toContain('Invalid date format');
115			});
116	
117			it('should report errors for invalid amounts', () => {
118				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
119	Visa,4514015001949444,6/10/2024,,"Test Store",,not-a-number,,`;
120				const result = parser.parse(csv);
121	
122				expect(result.errors.length).toBeGreaterThan(0);
123				expect(result.errors[0]).toContain('Invalid amount');
124			});
125	
126			it('should report errors for missing vendor name', () => {
127				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
128	Visa,4514015001949444,6/10/2024,,,,-100.00,,`;
129				const result = parser.parse(csv);
130	
131				expect(result.errors.length).toBeGreaterThan(0);
132				expect(result.errors[0]).toContain('Missing vendor name');
133			});
134	
135			it('should handle empty CSV', () => {
136				const result = parser.parse('');
137	
138				expect(result.transactions).toEqual([]);
139				expect(result.errors.length).toBeGreaterThan(0);
140			});
141	
142			it('should skip incomplete rows', () => {
143				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
144	Visa,4514015001949444,6/10/2024,,"Test Store",,-100.00,,
145	Incomplete Row
146	Visa,4514015001949444,6/11/2024,,"Another Store",,-50.00,,`;
147				const result = parser.parse(csv);
148	
149				expect(result.transactions).toHaveLength(2);
150				expect(result.transactions[0].vendor_name).toBe('Test Store');
151				expect(result.transactions[1].vendor_name).toBe('Another Store');
152			});
153	
154			it('should skip empty rows', () => {
155				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
156	Visa,4514015001949444,6/10/2024,,"Test Store",,-100.00,,
157	
158	Visa,4514015001949444,6/11/2024,,"Another Store",,-50.00,,`;
159				const result = parser.parse(csv);
160	
161				expect(result.transactions).toHaveLength(2);
162			});
163	
164			it('should handle CSV with BOM', () => {
165				const csv = loadCSV('RBCFinancialSample.csv');
166				const result = parser.parse(csv);
167	
168				expect(result.transactions).toHaveLength(2);
169				expect(result.errors).toEqual([]);
170			});
171	
172			it('should handle quoted fields correctly', () => {
173				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
174	"Visa","4514015001949444","6/10/2024",,"Test, Store",,-100.00,,`;
175				const result = parser.parse(csv);
176	
177				expect(result.transactions[0].vendor_name).toBe('Test, Store');
178			});
179	
180			it('should keep expense amounts with decimals as negative (#{#trn2d})', () => {
181				const csv = loadCSV('RBCFinancialSample.csv');
182				const result = parser.parse(csv);
183				expect(result.transactions[0].amount).toBe(-2445.0); // Expense stays negative
184			});
185	
186			it('should keep expense integer amounts as negative (#{#trn2d})', () => {
187				const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
188	Visa,4514015001949444,6/10/2024,,"Test Store",,-100,,`;
189				const result = parser.parse(csv);
190	
191				expect(result.transactions[0].amount).toBe(-100); // Expense stays negative
192			});
193		});
194	});
