1	// Base CSV parser interface and utilities for credit card and bank transaction parsing
2	
3	import type { ParsedTransaction, CSVParseResult } from '$lib/models/Transaction';
4	
5	/**
6	 * Base interface for all CSV parsers
7	 */
8	export interface ICSVParser {
9		/**
10		 * Parse a CSV string and return transactions
11		 * @param csvContent The raw CSV file content as a string
12		 * @returns CSVParseResult with parsed transactions and any errors
13		 */
14		parse(csvContent: string): CSVParseResult;
15	
16		/**
17		 * Validate if the CSV format matches this parser's expected format
18		 * @param csvContent The raw CSV file content as a string
19		 * @returns true if the format matches, false otherwise
20		 */
21		validateFormat(csvContent: string): boolean;
22	}
23	
24	/**
25	 * Base CSV parser with common utility methods
26	 */
27	export abstract class BaseCSVParser implements ICSVParser {
28		abstract parse(csvContent: string): CSVParseResult;
29		abstract validateFormat(csvContent: string): boolean;
30	
31		/**
32		 * Parse CSV string into rows and columns
33		 * Handles quoted fields with commas
34		 */
35		protected parseCSV(csvContent: string): string[][] {
36			const lines = csvContent.split(/\r?\n/);
37			const result: string[][] = [];
38	
39			// Strip a surviving surrounding "..." pair from a finalized field.
40			// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
41			// standard unwrap above reduces to `"-$33.00"` (literal " still present).
42			const stripOuterQuotes = (field: string): string => {
43				const trimmed = field.trim();
44				if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
45					return trimmed.slice(1, -1).trim();
46				}
47				return trimmed;
48			};
49	
50			for (const line of lines) {
51				if (!line.trim()) continue;
52	
53				const row: string[] = [];
54				let currentField = '';
55				let inQuotes = false;
56	
57				for (let i = 0; i < line.length; i++) {
58					const char = line[i];
59	
60					if (char === '"') {
61						// Handle escaped quotes
62						if (inQuotes && line[i + 1] === '"') {
63							currentField += '"';
64							i++; // Skip next quote
65						} else {
66							inQuotes = !inQuotes;
67						}
68					} else if (char === ',' && !inQuotes) {
69						row.push(stripOuterQuotes(currentField));
70						currentField = '';
71					} else {
72						currentField += char;
73					}
74				}
75	
76				// Add the last field
77				row.push(stripOuterQuotes(currentField));
78				result.push(row);
79			}
80	
81			return result;
82		}
83	
84		/**
85		 * Parse a date string in MM/DD/YYYY or YYYY-MM-DD format to YYYY-MM-DD
86		 */
87		protected parseDate(dateStr: string): string | null {
88			try {
89				// Remove any leading/trailing whitespace
90				dateStr = dateStr.trim();
91	
92				// Try YYYY-MM-DD format (new EQ Bank format)
93				const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
94				if (ymdMatch) {
95					const [, year, month, day] = ymdMatch;
96					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
97				}
98	
99				// Try MM/DD/YYYY format
100				const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
101				if (mdyMatch) {
102					const [, month, day, year] = mdyMatch;
103					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
104				}
105	
106				// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
107				const dmmyMatch = dateStr.match(/^(\d{1,2})[\s\-]([A-Za-z]{3})[\.\s\-]*(\d{2,4})$/);
108				if (dmmyMatch) {
109					const [, day, monthStr, year] = dmmyMatch;
110					const monthMap: Record<string, string> = {
111						jan: '01',
112						feb: '02',
113						mar: '03',
114						apr: '04',
115						may: '05',
116						jun: '06',
117						jul: '07',
118						aug: '08',
119						sep: '09',
120						oct: '10',
121						nov: '11',
122						dec: '12'
123					};
124					const month = monthMap[monthStr.toLowerCase()];
125					if (month) {
126						const fullYear = year.length === 2 ? `20${year}` : year;
127						return `${fullYear}-${month}-${day.padStart(2, '0')}`;
128					}
129				}
130	
131				// Try DD Mon YYYY format with full month name
132				const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
133				if (dmonyMatch) {
134					const [, day, monthStr, year] = dmonyMatch;
135					const monthMap: Record<string, string> = {
136						january: '01',
137						february: '02',
138						march: '03',
139						april: '04',
140						may: '05',
141						june: '06',
142						july: '07',
143						august: '08',
144						september: '09',
145						october: '10',
146						november: '11',
147						december: '12'
148					};
149					const month = monthMap[monthStr.toLowerCase()];
150					if (month) {
151						return `${year}-${month}-${day.padStart(2, '0')}`;
152					}
153				}
154	
155				return null;
156			} catch {
157				return null;
158			}
159		}
160	
161		/**
162		 * Parse amount from string, handling currency symbols, commas, and parentheses for negatives
163		 */
164		protected parseAmount(amountStr: string): number | null {
165			try {
166				// Trim whitespace and any surrounding quote characters left over from
167				// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
168				// unwraps once to a value still containing literal " characters).
169				amountStr = amountStr.trim().replace(/^["']+|["']+$/g, '').trim();
170	
171				// Check if amount is in parentheses (negative)
172				const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
173				if (isNegative) {
174					amountStr = amountStr.slice(1, -1);
175				}
176	
177				// Remove currency symbols, commas, whitespace, and any embedded quotes
178				amountStr = amountStr.replace(/[$,\s"']/g, '');
179	
180				// Parse the number
181				const amount = parseFloat(amountStr);
182				if (isNaN(amount)) return null;
183	
184				return isNegative ? -Math.abs(amount) : amount;
185			} catch {
186				return null;
187			}
188		}
189	
190		/**
191		 * Remove BOM (Byte Order Mark) if present
192		 */
193		protected removeBOM(content: string): string {
194			if (content.charCodeAt(0) === 0xfeff) {
195				return content.slice(1);
196			}
197			return content;
198		}
199	
200		/**
201		 * Check if a header row contains expected columns (case-insensitive)
202		 */
203		protected hasExpectedColumns(header: string[], expectedColumns: string[]): boolean {
204			const headerLower = header.map((h) => h.toLowerCase().trim());
205			return expectedColumns.every((col) => headerLower.includes(col.toLowerCase()));
206		}
207	
208		/**
209		 * Normalizes transaction amounts to positive values for expenses.
210		 *
211		 * For user-friendly display, expenses should be positive and refunds/credits should be negative.
212		 * Different banks use different conventions:
213		 * - PC Financial, EQ Bank, RBC, TD Bank, Simplii, Wealth Simple: Use negative for expenses → Need inversion
214		 * - American Express: Already uses positive for expenses → No inversion needed
215		 *
216		 * @param amount - The parsed amount from CSV
217		 * @param invertSign - If true, inverts the sign (for banks using negative for expenses). Default: true
218		 * @returns Normalized amount (positive = expense, negative = refund/credit) or null if input is null
219		 *
220		 * @example
221		 * // PC Financial: -50.00 (expense) → keep as-is
222		 * normalizeAmount(-50.00, false) // Returns -50.00
223		 *
224		 * @example
225		 * // American Express: 50.00 (expense) → invert to -50.00
226		 * normalizeAmount(50.00, true) // Returns -50.00
227		 *
228		 * @example
229		 * // PC Financial: 25.00 (refund) → keep as-is
230		 * normalizeAmount(25.00, false) // Returns 25.00
231		 *
232		 * Specification: #{#trn1b}
233		 */
234		protected normalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
235			if (amount === null || amount === undefined) return null;
236			if (amount === 0) return 0;
237	
238			return invertSign ? amount * -1 : amount;
239		}
240	}
